gs_provision.config:
    1
    {{xml .Line.AccountLabel}}
    {{xml .Server.Host}}:{{.Server.Port}}
    {{xml .Line.Username}}
    {{xml .Line.AuthName}}
    {{xml .Line.Password}}
    {{xml .Line.DisplayName}}
    0
    {{div .Server.Expiry 60}}
{{- /* MWI (spec S-1): P99 = Subscribe for MWI [R8x6 TPL, R8x6 section 5; WP822 same key]; P33 = voicemail access number, defaulting to Hello's voicemail feature code. */}}
    1
    {{xml (or .Line.VoicemailCode "*97")}}
{{- /* Call waiting (phone-feature-parity S-18), written from the extension's flag so the phone agrees with Hello. P26063 = account 1 "Enable Call Waiting" (WP8x6) / "Disable Call Waiting" (WP822): 1 = on, 2 = off in both templates (wp8x6_config_1.0.3.39 reads 0 Default, 1 Yes, 2 No; wp810_822_825_config_1.0.11.83 reads 0 Default, 1 No, 2 Yes, the question inverted). P91 = the phone-wide switch: 0 = on, 1 = off in both. P186 = "Enable Call Waiting Tone" (WP8x6 and WP820 templates): 0 = tone, 1 = no tone; the WP822 template has no such key and ignores it, its tone is P347/P1555 which stay at the phone default. Taken from Grandstream's published config templates, not yet confirmed on a phone (verify, lab item 26). */}}
{{- /* The WP856 template (wp856_config_1.0.3.16: "Enable Call Waiting. 0 Default, 1 No, 2 Yes") reads P26063 the other way round: 2 = on, 1 = off, and has no P91 or P186. */}}
{{- if .Phone.CWInverted}}
    {{if .Line.CallWaiting}}2{{else}}1{{end}}
{{- else if .Line.CallWaiting}}
    1
    0
    0
{{- else}}
    2
    1
    1
{{- end}}
{{- range $i, $k := .BLF}}

1

0

{{xml $k.Number}}
{{- end}}

    1
{{- /* Paging button and multicast paging (phone-feature-parity S-30, phonebooks-ptt P-15). Keys from Grandstream's own config templates wp8x6_config_1.0.3.39 and wp810_822_825_config_1.0.11.83 (config-template_09302026) and the WP8x6 Administration Guide "PTT/Paging": P22208 multicast paging on, P1568 codec (0 PCMU, 8 PCMA, 9 G.722), P1569 and up listening address and label pairs (ten slots); the WP8x6 only: P22556 PTT/Paging, P82317 side key (0 PTT/Paging), P22177 PTT, P22183 PTT/group paging address, P22184 default channel, P22179 accept while busy, P22180 codec, channels 1 to 25 at P82001 + 5 (n-1): available, transmit, subscribe, join, name. P26072 (WP8x6) plays the warning beep before an auto answer and P26071 (WP8x6) does not mute on answer. All unverified on a phone (verify). */}}
{{- if .Phone.PTTCapable}}
    1
    0
{{- end}}
{{- with .Multicast}}
    1
    {{.GSCodec}}
{{- range .ListenSlots}}

{{xml .HostPort}}

{{xml .Label}}
{{- end}}
{{- end}}
{{- if or .PTT (and .Multicast .Multicast.PagingKey)}}
    1
    0
{{- end}}
{{- with .PTT}}
    1
    {{xml .Address}}
    {{.DefaultChannel}}
    {{.AcceptBusy}}
    {{.CodecGS}}
{{- range .Channels}}

{{.Available}}

{{.Transmit}}

{{.Subscribe}}

{{.Available}}

{{xml .Label}}
{{- end}}
{{- end}}
    {{xml .Phone.AdminPassword}}
    {{urlvia .Prov.URL}}
{{- with .Prov.CACertPEM}}
    {{xml .}}
{{- end}}
    {{xml (noscheme .Prov.URL)}}
    0
    1
    {{div .Prov.ResyncSeconds 60}}
{{- /* Check-sync (spec S-5): P95030 = 0 so a plain check-sync re-provisions without a reboot (WP8x6 fw 1.0.3.20 and later) [R8x6 section 1]; P4428 = 1 authenticates the NOTIFY, which hello-sip answers from the device's HA1. */}}
    0
    1
{{- with .Book}}
    3
    {{xml .HostPath}}
    {{.RefreshMinutes}}
    1
{{- end}}
    {{xml .Time.NTP}}
{{- with .Time.TZ.POSIX}}
    {{xml .}}
    {{xml .}}
{{- end}}
{{- with .Firmware}}
    {{.Via}}
    {{xml (noscheme .Dir)}}


    0
{{- end}}
